-- Phase 0 foundation: tenant context, tenancy, minimal catalog, storage structure.
--
-- Conventions (docs/phase-0-build-plan.md, Section 5.3):
-- * Every tenant table has shop_id and a composite primary key (shop_id, id), so foreign keys
--   between tenant tables are composite and cannot point into another shop.
-- * Row-level security limits the runtime role (airstock_app) to the shop set in the
--   transaction-local setting app.shop_id. The runtime never connects as the owner.
-- * IDs are UUIDv7 generated by the application.

create function app_shop_id() returns uuid
  language sql stable
  as $$ select nullif(current_setting('app.shop_id', true), '')::uuid $$;

create function app_user_id() returns uuid
  language sql stable
  as $$ select nullif(current_setting('app.user_id', true), '')::uuid $$;

-- Tenancy ---------------------------------------------------------------------------------

create table users (
  id uuid primary key,
  workos_user_id text unique,
  email text not null,
  display_name text,
  created_at timestamptz not null default now()
);

create table shops (
  id uuid primary key,
  name text not null check (length(name) between 1 and 200),
  currency char(3) not null check (currency ~ '^[A-Z]{3}$'),
  timezone text not null,
  created_by uuid not null references users (id),
  created_at timestamptz not null default now(),
  version integer not null default 1
);

create table memberships (
  shop_id uuid not null references shops (id),
  id uuid not null,
  user_id uuid not null references users (id),
  role text not null check (role in ('owner', 'manager', 'catalog_editor', 'inventory_operator', 'viewer')),
  -- false means the member only sees and acts on the warehouses or locations listed in
  -- membership_location_scopes (C31, PRD 2.4).
  all_locations boolean not null default true,
  status text not null default 'active' check (status in ('active', 'removed')),
  created_at timestamptz not null default now(),
  version integer not null default 1,
  primary key (shop_id, id),
  unique (shop_id, user_id)
);

create index memberships_user_idx on memberships (user_id) where status = 'active';

-- Catalog (minimal) -----------------------------------------------------------------------

create table products (
  shop_id uuid not null references shops (id),
  id uuid not null,
  name text not null check (length(name) between 1 and 500),
  description text,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1,
  primary key (shop_id, id)
);

create table variants (
  shop_id uuid not null,
  id uuid not null,
  product_id uuid not null,
  sku text not null check (length(sku) between 1 and 100),
  -- Uniqueness uses the normalized form: trimmed, inner whitespace collapsed, upper case.
  sku_normalized text not null,
  name text,
  options jsonb not null default '{}'::jsonb,
  price numeric(20, 6) check (price >= 0),
  base_unit text not null default 'each',
  -- Permitted decimal places for quantities in the base unit (PRD 6.7). 0 = whole units.
  quantity_scale smallint not null default 0 check (quantity_scale between 0 and 6),
  tracking_mode text not null default 'none' check (tracking_mode in ('none', 'lot', 'lot_expiry', 'serial')),
  is_default boolean not null default false,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1,
  primary key (shop_id, id),
  unique (shop_id, sku_normalized),
  foreign key (shop_id, product_id) references products (shop_id, id)
);

-- Storage ---------------------------------------------------------------------------------

create table warehouses (
  shop_id uuid not null references shops (id),
  id uuid not null,
  name text not null check (length(name) between 1 and 200),
  ownership text not null default 'owned' check (ownership in ('owned', 'rented', 'third_party')),
  operator_name text,
  timezone text,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  version integer not null default 1,
  primary key (shop_id, id)
);

create table locations (
  shop_id uuid not null,
  id uuid not null,
  warehouse_id uuid not null,
  parent_id uuid,
  name text not null check (length(name) between 1 and 200),
  code text,
  -- Human-readable path for sorting pick lists, for example "Main/A/03".
  path text not null,
  -- The warehouse ID, then every ancestor location, then this location. Location scopes
  -- match on overlap, so scoping a member to a warehouse covers all of its locations.
  path_ids uuid[] not null,
  fulfillment_eligible boolean not null default true,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  version integer not null default 1,
  primary key (shop_id, id),
  foreign key (shop_id, warehouse_id) references warehouses (shop_id, id),
  foreign key (shop_id, parent_id) references locations (shop_id, id)
);

create index locations_parent_idx on locations (shop_id, parent_id);
create index locations_path_ids_idx on locations using gin (path_ids);

create table membership_location_scopes (
  shop_id uuid not null,
  membership_id uuid not null,
  -- A warehouse ID or a location ID; both appear in locations.path_ids.
  scope_id uuid not null,
  primary key (shop_id, membership_id, scope_id),
  foreign key (shop_id, membership_id) references memberships (shop_id, id)
);

-- Row-level security ----------------------------------------------------------------------

alter table users enable row level security;
alter table shops enable row level security;
alter table memberships enable row level security;
alter table products enable row level security;
alter table variants enable row level security;
alter table warehouses enable row level security;
alter table locations enable row level security;
alter table membership_location_scopes enable row level security;

-- A user sees their own record and the members of the current shop.
create policy users_visible on users for select
  using (id = app_user_id() or exists (
    select 1 from memberships m where m.user_id = users.id and m.shop_id = app_shop_id()));
create policy users_insert on users for insert with check (id = app_user_id());
create policy users_update on users for update using (id = app_user_id());

-- A shop is visible when it is the current shop or the signed-in user is an active member.
create policy shops_visible on shops for select
  using (id = app_shop_id() or exists (
    select 1 from memberships m
    where m.shop_id = shops.id and m.user_id = app_user_id() and m.status = 'active'));
create policy shops_insert on shops for insert with check (id = app_shop_id());
create policy shops_update on shops for update using (id = app_shop_id());

create policy memberships_visible on memberships for select
  using (shop_id = app_shop_id() or user_id = app_user_id());
create policy memberships_write on memberships for insert with check (shop_id = app_shop_id());
create policy memberships_update on memberships for update using (shop_id = app_shop_id());

create policy tenant_isolation on products using (shop_id = app_shop_id()) with check (shop_id = app_shop_id());
create policy tenant_isolation on variants using (shop_id = app_shop_id()) with check (shop_id = app_shop_id());
create policy tenant_isolation on warehouses using (shop_id = app_shop_id()) with check (shop_id = app_shop_id());
create policy tenant_isolation on locations using (shop_id = app_shop_id()) with check (shop_id = app_shop_id());
create policy tenant_isolation on membership_location_scopes using (shop_id = app_shop_id()) with check (shop_id = app_shop_id());

grant usage on schema public to airstock_app;
grant execute on function app_shop_id(), app_user_id() to airstock_app;
grant select, insert, update on users, shops, memberships, products, variants, warehouses, locations to airstock_app;
grant select, insert, delete on membership_location_scopes to airstock_app;
